import { afterEach, describe, expect, it, vi } from 'vitest';
import {
  createTaxonomyProductionHarness,
  taxonomyDefinitionVersionsPath,
  taxonomyDefinitionWriteRequest,
} from './taxonomy-definition.test-support';

afterEach(() => {
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
});

const WRITE_PATH = '/api/v1/cms/taxonomies/versions';
/** BE03c 1298-1302: not generated by the operation catalog -> scrubbed 500. */
const PROVIDER_FAULTS: readonly (readonly [string, number, unknown])[] = [
  ['PGRST202 function not found', 404, { code: 'PGRST202', message: 'x' }],
  ['PGRST301 bad service credential', 401, { code: 'PGRST301', message: 'x' }],
  [
    'SQLSTATE 42702 ambiguous column',
    400,
    { code: '42702', message: 'column reference "actor_id" is ambiguous' },
  ],
  ['SQLSTATE 42501 insufficient privilege', 403, { code: '42501' }],
  [
    'SQLSTATE 40001 engine serialization failure',
    409,
    { code: '40001', message: 'could not serialize access' },
  ],
  ['payload without any code', 404, { message: 'NOT_FOUND' }],
  ['unsupported 4xx status', 418, { code: 'PGRST999' }],
  ['array payload', 400, ['NOT_FOUND']],
  ['string payload', 404, 'NOT_FOUND'],
];
const operations = [
  {
    name: 'definition write',
    path: WRITE_PATH,
    init: () => taxonomyDefinitionWriteRequest(),
  },
  {
    name: 'versions read',
    path: taxonomyDefinitionVersionsPath(),
    init: () => undefined,
  },
] as const;

describe.each(operations)(
  'taxonomy $name: provider 4xx without a product token',
  (operation) => {
    it.each(PROVIDER_FAULTS)(
      'scrubs %s to 500 INTERNAL_ERROR',
      async (_name, status, payload) => {
        const fetchImpl = vi.fn<typeof fetch>(async () =>
          Response.json(payload, { status }),
        );
        const h = createTaxonomyProductionHarness(fetchImpl);
        const response = await h.request(operation.path, operation.init());
        expect(response.status).toBe(500);
        const body: unknown = await response.json();
        expect(body).toMatchObject({ code: 'INTERNAL_ERROR' });
        expect(JSON.stringify(body)).not.toMatch(/PGRST|42702|actor_id/);
        expect(fetchImpl).toHaveBeenCalledTimes(1);
      },
    );

    it('keeps a structured product token answer', async () => {
      const fetchImpl = vi.fn<typeof fetch>(async () =>
        Response.json({ code: 'NOT_FOUND' }, { status: 404 }),
      );
      const h = createTaxonomyProductionHarness(fetchImpl);
      const response = await h.request(operation.path, operation.init());
      expect(response.status).toBe(404);
      expect(await response.json()).toMatchObject({
        code: 'TAXONOMY_NOT_FOUND',
      });
    });
  },
);

describe.each(operations)(
  'taxonomy $name: a response-contract failure is a retryable 502',
  (operation) => {
    it('answers a malformed 2xx body as 502 with retryable true (BE00 172)', async () => {
      const fetchImpl = vi.fn<typeof fetch>(async () =>
        Response.json({ bad: true }, { status: 200 }),
      );
      const h = createTaxonomyProductionHarness(fetchImpl);
      const response = await h.request(operation.path, operation.init());
      expect(response.status).toBe(502);
      expect(await response.json()).toMatchObject({
        code: 'DEPENDENCY_UNAVAILABLE',
        details: { dependencyClass: 'cms_composition', retryable: true },
      });
    });
  },
);
